// TODO: use `T extends (infer U)[] ? U : never`
type ElementType<T> = T;

type A = ElementType<string[]>; // want: string
const first: A = 'hello';
console.log(first.toUpperCase());

solution.code:
type ElementType<T> = T extends (infer U)[] ? U : never;

type A = ElementType<string[]>; // string
const first: A = 'hello';
console.log(first.toUpperCase());

brokenCode.code:
// BUG: naked T distributes. For a union, this evaluates per-member,
// and for never (the empty union) it distributes to never, giving wrong results.
type IsNever<T> = T extends never ? true : false;

type A = IsNever<never>;        // resolves to never, NOT true
type B = IsNever<string | number>; // distributes -> false | false -> false (ok by luck)

const a: A = true as any;
console.log('see hover types: A is never, not true');

solution.code:
type IsNever<T> = [T] extends [never] ? true : false;

type A = IsNever<never>;            // true
type B = IsNever<string | number>; // false
console.log('A is now true, B is false');

type UnwrapPromise<T> = T extends Promise<infer U> ? UnwrapPromise<U> : T;

type A = UnwrapPromise<Promise<Promise<string>>>; // string
type B = UnwrapPromise<number>;                   // number

async function demo(): Promise<void> {
  const value: A = await Promise.resolve(Promise.resolve('done'));
  console.log(value.toUpperCase());
}
demo();
